//! Display shapes sent to the UI as JSON (TypeScript types generated by ts-rs).
//!
//! These are flat and string-based on purpose: the UI draws diagrams and tables from them and
//! never needs to understand ids, arenas or bitsets.

use crate::dfa::Dfa;
use crate::gnfa::Gnfa;
use crate::ids::StateId;
use crate::nfa::{Label, Nfa, StateGroup};
use crate::object::Object;
use crate::state::{Origin, StateInfo};
use crate::trace::Trace;
use serde::Serialize;
use ts_rs::TS;

/// One state as drawn: a circle, double if accepting, with an arrow in if it is the start.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct StateView {
    pub name: String,
    pub start: bool,
    pub accept: bool,
    /// Added automatically to make δ total (drawn dashed).
    pub trap: bool,
    /// Why the state exists, when a construction made it.
    pub origin: Option<String>,
}

/// One arrow as drawn; parallel arrows are merged into one label, as the book does ("0,1").
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct EdgeView {
    pub from: u32,
    pub to: u32,
    pub label: String,
}

/// A row of the δ-table.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct TableRowView {
    pub state: String,
    pub cells: Vec<String>,
}

/// δ laid out like the book's tables (an ε column for NFAs; a matrix for GNFAs).
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct TableView {
    pub columns: Vec<String>,
    pub rows: Vec<TableRowView>,
}

/// A box around the states one sub-expression produced (regex → NFA, Lemma 1.55).
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct GroupView {
    pub label: String,
    pub states: Vec<u32>,
    pub parent: Option<u32>,
}

/// A machine ready to draw: diagram data plus its δ-table.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct MachineView {
    /// "dfa", "nfa" or "gnfa".
    pub kind: String,
    pub states: Vec<StateView>,
    pub sigma: Vec<String>,
    pub edges: Vec<EdgeView>,
    pub table: TableView,
    /// Layout clusters (empty except for NFAs built from regular expressions).
    pub groups: Vec<GroupView>,
}

/// One trace step, with edges given as indices into the final machine's `edges`.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct StepView {
    pub rule: String,
    /// The step's heading, e.g. "Theorem 1.45 · 0∪1".
    pub title: String,
    pub message: String,
    pub add_states: Vec<u32>,
    pub add_edges: Vec<u32>,
    pub focus: Vec<u32>,
    pub start: Option<u32>,
    pub accept: Option<Vec<u32>>,
    pub snapshot: Option<MachineView>,
}

/// The steps of the conversion that produced an object.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[ts(export)]
pub struct TraceView {
    /// e.g. "Theorem 1.39 — subset construction".
    pub title: String,
    pub steps: Vec<StepView>,
    pub truncated: bool,
}

fn state_view(info: &StateInfo, start: bool, accept: bool) -> StateView {
    // `match &info.origin` borrows the origin while matching, so nothing is moved out of `info`.
    let origin = match &info.origin {
        Origin::User | Origin::Copied => None,
        Origin::Subset(_) => {
            Some("subset of the NFA's states, ε-closed (Theorem 1.39)".to_string())
        }
        Origin::Trap => Some("trap state, added so that δ is total (Definition 1.5)".to_string()),
        Origin::Rule(r) => Some((*r).to_string()),
    };
    StateView {
        name: info.name.clone(),
        start,
        accept,
        trap: info.origin == Origin::Trap,
        origin,
    }
}

/// Merges parallel arrows: one EdgeView per (from, to) pair, labels joined in the given order.
fn merge_edges(arrows: Vec<(u32, u32, String)>) -> Vec<EdgeView> {
    let mut edges: Vec<EdgeView> = Vec::new();
    for (from, to, label) in arrows {
        // `.iter_mut().find(...)` returns a mutable reference to the first match, if any.
        if let Some(e) = edges.iter_mut().find(|e| e.from == from && e.to == to) {
            e.label.push(',');
            e.label.push_str(&label);
        } else {
            edges.push(EdgeView { from, to, label });
        }
    }
    edges
}

fn dfa_view(m: &Dfa) -> MachineView {
    let states = m
        .states
        .iter()
        .enumerate()
        .map(|(i, s)| state_view(s, i == m.start.index(), m.accept.contains(i)))
        .collect();
    let mut arrows = Vec::new();
    let mut rows = Vec::new();
    for q in 0..m.num_states() {
        let q = StateId::from_index(q);
        let mut cells = Vec::new();
        for a in m.sigma.ids() {
            let r = m.next(q, a);
            arrows.push((q.0, r.0, m.sigma.display(a)));
            cells.push(m.name(r).to_string());
        }
        rows.push(TableRowView {
            state: m.name(q).to_string(),
            cells,
        });
    }
    MachineView {
        groups: Vec::new(),
        kind: "dfa".into(),
        states,
        sigma: m.sigma.names().to_vec(),
        edges: merge_edges(arrows),
        table: TableView {
            columns: m.sigma.ids().map(|a| m.sigma.display(a)).collect(),
            rows,
        },
    }
}

fn nfa_view(m: &Nfa) -> MachineView {
    let states = m
        .states
        .iter()
        .enumerate()
        .map(|(i, s)| state_view(s, i == m.start.index(), m.accept.contains(i)))
        .collect();
    let label_text = |l: Label| match l {
        Label::Eps => "ε".to_string(),
        Label::Sym(a) => m.sigma.display(a),
    };
    let mut arrows = Vec::new();
    let mut rows = Vec::new();
    // Columns in the book's order: the symbols of Σ, then ε (Example 1.38).
    let mut columns: Vec<Label> = m.sigma.ids().map(Label::Sym).collect();
    columns.push(Label::Eps);
    for q in 0..m.num_states() {
        let q = StateId::from_index(q);
        let mut edges = m.edges(q).to_vec();
        // `.sort()` orders tuples field by field; Label orders ε first, then symbols in Σ order.
        edges.sort();
        for (l, r) in &edges {
            arrows.push((q.0, r.0, label_text(*l)));
        }
        let cells = columns
            .iter()
            .map(|&col| {
                let targets: Vec<&str> = edges
                    .iter()
                    .filter(|(l, _)| *l == col)
                    .map(|(_, r)| m.name(*r))
                    .collect();
                if targets.is_empty() {
                    "∅".to_string()
                } else {
                    format!("{{{}}}", targets.join(", "))
                }
            })
            .collect();
        rows.push(TableRowView {
            state: m.name(q).to_string(),
            cells,
        });
    }
    MachineView {
        groups: m.groups.iter().map(group_view).collect(),
        kind: "nfa".into(),
        states,
        sigma: m.sigma.names().to_vec(),
        edges: merge_edges(arrows),
        table: TableView {
            columns: columns.into_iter().map(label_text).collect(),
            rows,
        },
    }
}

fn group_view(g: &StateGroup) -> GroupView {
    GroupView {
        label: g.label.clone(),
        states: g.states.iter().map(|q| q.0).collect(),
        parent: g.parent.map(|p| p as u32),
    }
}

fn gnfa_view(g: &Gnfa) -> MachineView {
    let n = g.num_states();
    let states = g
        .states
        .iter()
        .enumerate()
        .map(|(i, s)| state_view(s, i == g.start.index(), i == g.accept.index()))
        .collect();
    let mut edges = Vec::new();
    for i in 0..n {
        for j in 0..n {
            let (qi, qj) = (StateId::from_index(i), StateId::from_index(j));
            // ∅-labelled arrows are hidden, as in Figure 1.67.
            if g.label(qi, qj) != g.arena.empty() {
                edges.push(EdgeView {
                    from: qi.0,
                    to: qj.0,
                    label: g.label_text(qi, qj),
                });
            }
        }
    }
    let cols: Vec<StateId> = (0..n)
        .map(StateId::from_index)
        .filter(|&q| q != g.start)
        .collect();
    let rows = (0..n)
        .map(StateId::from_index)
        .filter(|&q| q != g.accept)
        .map(|qi| TableRowView {
            state: g.name(qi).to_string(),
            cells: cols.iter().map(|&qj| g.label_text(qi, qj)).collect(),
        })
        .collect();
    MachineView {
        groups: Vec::new(),
        kind: "gnfa".into(),
        states,
        sigma: g.sigma.names().to_vec(),
        edges,
        table: TableView {
            columns: cols.iter().map(|&q| g.name(q).to_string()).collect(),
            rows,
        },
    }
}

/// The drawable view of a machine (None for a regular expression).
pub fn machine_view(object: &Object) -> Option<MachineView> {
    match object {
        Object::Dfa(m) => Some(dfa_view(m)),
        Object::Nfa(m) => Some(nfa_view(m)),
        Object::Gnfa(g) => Some(gnfa_view(g)),
        Object::Regex(_) => None,
    }
}

/// Converts a trace into its view, resolving arrows against the final machine's merged edges.
pub fn trace_view(title: &str, trace: &Trace, result: &MachineView) -> TraceView {
    let ids = |v: &[StateId]| v.iter().map(|q| q.0).collect::<Vec<u32>>();
    let steps = trace
        .steps
        .iter()
        .map(|s| StepView {
            rule: s.rule.to_string(),
            title: s.title.clone().unwrap_or_else(|| s.rule.to_string()),
            message: s.message.clone(),
            add_states: ids(&s.add_states),
            add_edges: s
                .add_edges
                .iter()
                // `.filter_map(f)` keeps only the `Some` results of f.
                .filter_map(|(a, b)| {
                    result
                        .edges
                        .iter()
                        .position(|e| e.from == a.0 && e.to == b.0)
                        .map(|i| i as u32)
                })
                .collect(),
            focus: ids(&s.focus),
            start: s.start.map(|q| q.0),
            accept: s.accept.as_deref().map(ids),
            snapshot: s.snapshot.as_deref().and_then(machine_view),
        })
        .collect();
    TraceView {
        title: title.to_string(),
        steps,
        truncated: trace.truncated,
    }
}
